#include "Markdown.h" // assuming you have a Markdown parsing library

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream html;
    Markdown markdown_parser;

    // Convert Markdown to HTML
    markdown_parser.Convert(markdown, [&](const std::string& token, const std::string& type) {
        if (type == "text") {
            html << token;
        } else if (type == "heading") {
            html << "<h" << (token[1] - '1') << ">" << token.substr(2) << "</h" << (token[1] - '1') << ">";
        } else if (type == "bold") {
            html << "<strong>" << token << "</strong>";
        } else if (type == "italic") {
            html << "<em>" << token << "</em>";
        } else if (type == "link") {
            std::size_t pos = token.find(" ");
            html << "<a href='" << token.substr(0, pos) << "'>" << token.substr(pos + 1) << "</a>";
        } else if (type == "image") {
            std::size_t pos = token.find(" ");
            html << "<img src='" << token.substr(0, pos) << "' alt='" << token.substr(pos + 1) << "'>";
        }
    });

    return html.str();
}

int main() {
    std::string markdown = "Hello **world**! \n\n# Header\n\n[Link](https://example.com) \n![Image](https://example.com/image.png)";
    std::string html = markdown_to_html(markdown);
