Here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string filename, word;
    int count = 0;

    // Prompt user for input file name and search word
    std::cout << "Enter the name of the input file: ";
    std::cin >> filename;

    std::cout << "Enter the word to search for: ";
    std::cin >> word;

    // Open input file
    std::ifstream file(filename);
    if (!file) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

    // Read file line by line and count occurrences
    std::string line;
    while (getline(file, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // convert line to lowercase
        std::size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) { // search for word in line
            count++; // increment count for each occurrence
            pos += word.length(); // move search position forward to next occurrence
        }
    }

    // Close input file
    file.close();

    // Print count
    std::cout << "The word \"" << word << "\" appears " << count << " times in " << filename << "." << std::endl;

    return 0;
}
```

This program prompts the user for the input file name and search word, opens the input file, reads it line by line, converts each line to lowercase, searches for the specified word in each line, and increments a count for each occurrence. After processing all lines, the program closes the input file and prints the final count.

